# 一般實支「方案數字」對照表：逐字轉錄自 regular/products.json 人工覆核欄位（room_limit/misc_limit/surgery_limit/opd_surgery），
# 以 tii 名稱關鍵字比對避免索引錯位。None = 條款無該項或未確認。不推估任何數字。
def P(names,room,misc,surg=None,opd=None):
    n=len(names);L=lambda v:v if isinstance(v,list) else [v]*n
    return [dict(plan=a,room=b,misc=c,surg_max=d,opd=e) for a,b,c,d,e in zip(names,L(room),L(misc),L(surg),L(opd))]
